// ========================================
// 闸机模拟器 - 解析WebSocket消息
// ========================================

let data;

// ========================================
// 1. 解析WebSocket消息
// ========================================

try {
    if (typeof msg.payload === "string") {
        data = JSON.parse(msg.payload);
    } else {
        data = msg.payload;
    }
} catch (e) {
    node.error("收到的数据不是合法JSON：" + msg.payload, msg);

    node.status({
        fill: "red",
        shape: "ring",
        text: "JSON解析失败"
    });

    return null;
}


// ========================================
// 3. 获取消息类型
// ========================================

const command = data.command;



node.warn(
    "命令类型：" +
    command
);




// ========================================
// 5. 获取 data.xxx
// ========================================

const serial = data.serial;

if (typeof serial !== "string" && command!="FACE_MATCH") {

    node.error(
        "消息1中没有找到序列号" +
        JSON.stringify(data.data),
        msg
    );

    node.status({
        fill: "red",
        shape: "ring",
        text: "缺少 data.serial"
    });

    return null;
}
if(command=="START_COLLECTION"){
    msg.payload = "next";
    flow.set("count", 0);
}

// ========================================
// 6. 保存参数
// ========================================
msg.command = command;
msg.serial = serial;
msg.originalMessage = data;


// ========================================
// 7. 显示状态
// ========================================

node.status({
    fill: "green",
    shape: "dot",
    text: "收到指令：" + command
});




return msg;

const data = msg.payload || {};
var serial = msg.serial;
if (msg.command == "START_CAPTURE_FACE" || msg.command == "START_CAPTURE_FINGER_SINGLE"){
    serial = msg.serial.split("_")[0]; 
}

if (!serial) {
    node.error("消息缺少serial", msg);
    return null;
}

const pending = flow.get("passengerInfo") || {};
const request = pending[serial];

if (!request) {
    node.warn("找不到Pending请求：" + serial);

    msg.payload = JSON.stringify({
        message: "取芯片信息ERROR",
        requestId: serial,
        error: "REQUEST_NOT_FOUND"
    });

    return msg;
}

// ========================================
// 找到了对应的A
// ========================================
msg.docData = request.data || {};

return msg;

msg.payload = JSON.stringify({
  "type": "gate.capture",
  "case_id": msg.docData.DocNum,
  "timestamp": new Date().toISOString(),
  "gate_id": "G01",
  "expected": {
    "allow_pass": msg.docData.AllowPass,
    "failed_node": msg.docData.FailedNode
  },
  "capture": {
    "passenger_name": msg.docData.PassengerName,
    "cert_type": msg.docData.DocType,
    "cert_no": msg.serial,
    "photo_base64": msg.docData.CHIPFace
  }
});

// ★ 关键改动：清掉 _session。
// WebSocket In 节点会给消息打上 msg._session（发起方那个连接），
// WebSocket Out（Listen on）看到 _session 就"只回给发起方"；
// 删掉它之后，消息会广播给连在同一个路径上的所有客户端 ——
// 被测程序照旧收到（广播包含它），本自动化程序也能收到。
delete msg._session;

node.warn("！！！！！！！！！！！" + msg.payload);
node.status({ fill: "green", shape: "dot", text:"发送预期结果（广播）"});

return msg;
